public class Short {
    public static void main(String[] args) {
        int i = 0, j = 0;
        boolean r = (i++ > 0) && (j++ > 0);
        boolean s = (++i > 0) || (j++ > 0);
        boolean t = (i > 0) ^ (j++ == 0);
        System.out.println(i + " " + j + " " + r + " " + s + " " + t);
    }
}

