public class Yield {
    public static void main(String[] args) {
        int key = 2;
        int x = switch (key) {
            case 1: yield 10;
            case 2: System.out.print("two ");
            case 3: System.out.print("three ");
            default: yield 30;
        };
        System.out.println(x);
    }
}

public class Exh {
    public static void main(String[] args) {
        int day = 3;
        String type = switch (day) {
            case 1, 7 -> "weekend";
            case 2, 3, 4, 5, 6 -> "weekday";
        };
        System.out.println(type);
    }
}

public class Arrow {
    public static void main(String[] args) {
        String code = "B";
        int pts = switch (code) {
            case "A" -> 4;
            case "B", "C" -> {
                System.out.print("ok ");
                yield 3;
            }
            default -> 0;
        };
        System.out.println(pts);
    }
}

